INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (8, 3, 'theory', 'Quiz: permissions, users and privileges');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (8, 3, 0, 'A file has permissions rw-r-----. You are not the owner, but you are in the file''s group. What can you do?', '["Read and write, like the owner", "Nothing: \"others\" have no rights", "Read and execute", "Only read: the group''s set applies, because it is the first one that fits"]', 3, 'The kernel picks the first set that fits: owner, then group, then others. The sets are not added together.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (8, 3, 1, 'What permissions will a new file get if umask is 027 (created with 666)?', '["750", "640: the mask bits 027 are subtracted from 666", "644", "600"]', 1, 'The mask removes bits: write (2) is denied for the group, everything (7) for others. From rw-rw-rw- you get rw-r-----, that is 640.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (8, 3, 2, 'What does the setuid bit on an executable file do?', '["At launch the process''s effective uid becomes equal to the file''s owner", "The file can be run without the execute permission", "The file is visible to all users", "The file cannot be deleted"]', 0, 'This is how passwd writes to shadow, which is closed to everyone. The real uid stays yours, and such programs are kept under strict control: a bug in them hands out someone else''s rights.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (8, 3, 3, 'What is the sticky bit for on a shared directory like /tmp?', '["Files in the directory are encrypted automatically", "The directory''s contents are stored only in memory", "Only the file''s owner (or the directory''s owner and root) can delete or rename a file", "Other users cannot read the files"]', 2, 'Without sticky, write permission on a directory lets you delete other people''s names: deleting is an edit of the directory. Sticky forbids that.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (8, 3, 4, 'What are capabilities in Linux?', '["A list of files you have access to", "Root''s power split into about forty separate privileges, with a process given only the ones it needs", "A user''s supplementary groups", "Permissions to run programs in a container"]', 1, 'A web server needs only binding to a privileged port, and does not need root. Containers drop almost all capabilities.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (8, 3, 5, 'The permissions rwxr-x--- written in octal are...', '["705", "570", "755", "750"]', 3, 'For the owner rwx = 4+2+1 = 7, for the group r-x = 4+1 = 5, for others --- = 0.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (8, 3, 6, 'What does the x permission on a directory give you?', '["The right to run the directory as a program", "The right to delete the whole directory", "The right to enter the directory and reach entries by name: without it the files inside cannot be opened, even if you know the name", "The right to see the list of names in the directory"]', 2, 'The list of names is r, and passing through the directory is x. That is why a directory is often --x: you can walk in, but you cannot list it.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (8, 3, 7, 'Why did the kernel split root''s omnipotence into capabilities?', '["To give a process only what it needs, for example the right to take ports below 1024, without the rest", "So that root can work without a password", "So that ordinary users can read any file", "To speed up file permission checks"]', 0, 'It used to be that a program needing a single port had to be given full root. Capabilities let it get by with just one: CAP_NET_BIND_SERVICE.');
